import sys
from decimal import Decimal, ROUND_HALF_UP

class ProductCalculator:
    def __init__(self, a, b):
        self.a = Decimal(str(a))
        self.b = Decimal(str(b))
        self.product = self.a * self.b

    def get_product(self):
        return self.product

def count_decimal_places(s):
    """Count the number of decimal places in a string representation of a number."""
    if '.' in s:
        return len(s.split('.')[1])
    return 0

def main():
    lines = []
    for _ in range(3):
        line = sys.stdin.readline().strip()
        if line:
            lines.append(line)

    max_decimals = 0
    calculators = []

    for line in lines:
        parts = line.split()
        a = parts[0].strip()
        b = parts[1].strip()

        dec_a = count_decimal_places(a)
        dec_b = count_decimal_places(b)
        max_decimals = max(max_decimals, dec_a, dec_b)

        calc = ProductCalculator(float(a), float(b))
        calculators.append(calc)

    total = sum(calc.get_product() for calc in calculators)

    # Determine output format
    if max_decimals == 0:
        # All integers - output as integer
        print(int(total))
    elif max_decimals <= 2:
        # Up to 2 decimal places
        result = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        print(f"{result:.2f}" if result != int(result) else int(result))
    else:
        # Up to 6 decimal places
        result = total.quantize(Decimal('0.000001'), rounding=ROUND_HALF_UP)
        print(f"{result:.6f}")

if __name__ == "__main__":
    main()
